# count 16 actually 4+6+3+3=16. so 2 squares + 2 L? 8+6 =14 no; 4 L? 4+12=16 => four Ls plus one square (4+12)
# enumerate tilings one square, four L triominoes
placements=[]
for r in range(4):
 for c in range(6):
  cells={(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
  if cells<=S: placements.append(('sq',cells))
for r in range(4):
 for c in range(6):
  box={(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
  for missing in box:
   cells=box-{missing}
   if cells<=S: placements.append(('L',cells))
sol=[]
def rec(left,chosen):
 if not left:
  sol.append(chosen);return
 if len(chosen)>5:return
 p=min(left,key=lambda x:sum(x in q[1] for q in placements))
 for typ,cells in placements:
  if p in cells and cells<=left and (typ!='sq' or sum(t=='sq' for t,_ in chosen)<1):rec(left-cells,chosen+[(typ,cells)])
rec(S,[])
len(sol),sol[:1]
